mapper.update:
UPDATE system_user
SET login_failed_count = #{failedCount},
    login_failure_window_started_at = #{windowStartedAt},
    login_locked_until = #{lockedUntil}
WHERE id = #{id}

where.if:
AND EXISTS ( SELECT 1 FROM system_user_org uo INNER JOIN system_org o ON o.id = uo.org_id WHERE uo.user_id = u.id
AND o.path_ids LIKE CONCAT(#{query.orgPathIds}, '%')
AND uo.org_id = #{query.orgId}
AND uo.is_primary = 1
AND uo.is_primary = 0
)

mapper.select:
SELECT DISTINCT ur.user_id
FROM system_user_role ur
INNER JOIN system_role r ON r.id = ur.role_id
WHERE ur.user_id > #{lastId}
  AND (

        ur.role_id IN

            #{roleId}



        OR


        r.role_code IN

            #{roleCode}


  )
ORDER BY ur.user_id ASC
LIMIT #{limit}
